package com.sobrenaturaldirector.spatial.model;

import java.util.*;import com.sobrenaturaldirector.domain.StableId;import com.sobrenaturaldirector.spatial.geometry.*;

public final class AbstractSpatialPlan {private final String id,blueprintId;private final LocalVec3i localOrigin;private final List<SpatialNodePlacement> nodes;private final List<SpatialConnectorPlacement> connectors;private final Map<String,LocalAnchor> anchors;private final SpatialFootprint footprint;private final SiteRequirements siteRequirements;private final SpatialBudget budget;private final int attempts,backtracks;public AbstractSpatialPlan(String id,String blueprintId,List<SpatialNodePlacement> nodes,List<SpatialConnectorPlacement> connectors,Map<String,LocalAnchor> anchors,SpatialFootprint footprint,SiteRequirements requirements,SpatialBudget budget,int attempts,int backtracks){this.id=StableId.require(id,"spatialPlanId");this.blueprintId=StableId.require(blueprintId,"blueprintId");localOrigin=new LocalVec3i(0,0,0);this.nodes=immutable(nodes);this.connectors=immutable(connectors);this.anchors=Collections.unmodifiableMap(new TreeMap<String,LocalAnchor>(anchors==null?Collections.<String,LocalAnchor>emptyMap():anchors));if(footprint==null||requirements==null||budget==null||attempts<0||backtracks<0)throw new IllegalArgumentException("invalid spatial plan");this.footprint=footprint;siteRequirements=requirements;this.budget=budget;this.attempts=attempts;this.backtracks=backtracks;}private static <T>List<T>immutable(Collection<T>x){return Collections.unmodifiableList(new ArrayList<T>(x==null?Collections.<T>emptyList():x));}public String getId(){return id;}public String getBlueprintId(){return blueprintId;}public LocalVec3i getLocalOrigin(){return localOrigin;}public List<SpatialNodePlacement> getNodes(){return nodes;}public List<SpatialConnectorPlacement> getConnectors(){return connectors;}public Map<String,LocalAnchor> getAnchors(){return anchors;}public SpatialFootprint getFootprint(){return footprint;}public SiteRequirements getSiteRequirements(){return siteRequirements;}public SpatialBudget getBudget(){return budget;}public int getAttempts(){return attempts;}public int getBacktracks(){return backtracks;}}
